#include<bits/stdc++.h>
using namespace std;
const int N=1000005;
int n,K;
int st[N],adj[2*N],eu[N],ev[N];
int lvl[N],lvlO[N],lvStart[N];        // 剥叶子的层号、按层排好的点、每层起点
int par[N],que[N],dn[N],upv[N];
int two[N],three[N],id1[N],id2[N];    // 邻居层号的第二大/第三大，以及最大的两个邻居
int nd[N],hd[N],nx[N],mk[N];
int stamp;

// 一条链上最多能删掉几个点。hl、hr：链两端外面还有没有分叉点接着
int calc(int len,int hl,int hr){
    int best=0;
    int hi=hr?len:len-1;
    for(int t=1;t<=len+1;t++)hd[t]=0;
    for(int p=1;p<=len;p++){
        int a=p-nd[p]+1;
        if(a<1)a=1;
        nx[p]=hd[a];
        hd[a]=p;
    }
    int mn=len+5;
    for(int i=len;i>=1;i--){
        for(int p=hd[i+1];p;p=nx[p]){
            int b=p+nd[p]-1;
            if(b<mn)mn=b;
        }
        if(i==1&&!hl)break;
        int j=hi<mn?hi:mn;
        if(j>=i&&j-i+1>best)best=j-i+1;
    }
    if(!hr){
        int mx=0;
        for(int i=len;i>=1;i--){
            int a=i-nd[i]+1;
            if(a>mx)mx=a;
            if(mx<=i&&len-i+1>best)best=len-i+1;
        }
    }
    if(!hl){
        int mnb=len+5;
        for(int j=1;j<=len;j++){
            int b=j+nd[j]-1;
            if(b<mnb)mnb=b;
            if(mnb>=j&&j>best)best=j;
        }
    }
    return best;
}

bool check(int r){
    int from=lvStart[r+1];
    int cnt=n-from;                 // 核心点数
    if(cnt<=K)return true;
    int needDel=cnt-K;              // 必须从核心删掉的点数
    if(needDel>2*r)return false;
    int lim=r+1;
    stamp++;
    int mxp=0;
    for(int idx=from;idx<n;idx++){
        int u=lvlO[idx];
        if(mk[u]==stamp)continue;
        int c1;
        if(three[u]>=lim)c1=3;
        else if(two[u]>=lim)c1=2;
        else c1=1;
        if(c1==3)continue;          // 分叉点不能删
        if(c1==2&&three[id1[u]]<lim&&three[id2[u]]<lim)continue;
        // 从链端出发走完整条链，顺手算出每个点能删多少
        int len=0,pre=0,cur=u,hl=0,hr=0;
        while(cur){
            int c2=(three[cur]>=lim)?3:(two[cur]>=lim?2:1);
            int a=id1[cur],b=(c2>=2)?id2[cur]:0;
            int f=0,pu=par[cur];
            for(int e=st[cur];e<st[cur+1];e++){
                int v=adj[e];
                if(v==a||v==b)continue;
                int h=(v==pu?upv[cur]:dn[v])+1;
                if(h>f)f=h;
            }
            int need=r-f;
            nd[++len]=need>0?need:0;
            mk[cur]=stamp;
            int nxt=0,anc=0;
            if(three[a]>=lim)anc=1;
            else if(a!=pre)nxt=a;
            if(b&&three[b]>=lim)anc=1;
            else if(b&&b!=pre&&!nxt)nxt=b;
            if(len==1)hl=anc;
            hr=anc;
            pre=cur;
            cur=nxt;
        }
        int got=calc(len,hl,hr);
        if(got>mxp){
            mxp=got;
            if(mxp>=needDel)return true;
        }
    }
    return mxp>=needDel;
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);
    int c,T;
    cin>>c>>T;
    while(T--){
        cin>>n>>K;
        for(int i=1;i<n;i++)cin>>eu[i]>>ev[i];
        if(K>=n){cout<<0<<'\n';continue;}
        if(K==n-1){cout<<1<<'\n';continue;}
        // 一、建图（CSR）
        for(int i=1;i<=n;i++){st[i]=0;lvl[i]=0;}
        st[n+1]=0;
        for(int i=1;i<n;i++){st[eu[i]]++;st[ev[i]]++;}
        int s=0;
        for(int i=1;i<=n;i++){int d=st[i];st[i]=s;s+=d;}
        st[n+1]=s;
        for(int i=1;i<=n;i++)que[i]=st[i];
        for(int i=1;i<n;i++){
            adj[que[eu[i]]++]=ev[i];
            adj[que[ev[i]]++]=eu[i];
        }
        // 二、剥叶子分层
        for(int i=1;i<=n;i++)dn[i]=st[i+1]-st[i];
        int t=0;
        for(int i=1;i<=n;i++)
            if(dn[i]<=1){lvlO[t++]=i;lvl[i]=1;}
        int h=0,lev=1;
        lvStart[1]=0;
        while(h<t){
            int e2=t;
            while(h<e2){
                int u=lvlO[h++];
                for(int e=st[u];e<st[u+1];e++){
                    int v=adj[e];
                    if(lvl[v]==0&&--dn[v]==1){lvl[v]=lev+1;lvlO[t++]=v;}
                }
            }
            lev++;
            lvStart[lev]=e2;
        }
        int maxLev=lev-1;
        // 三、每个点记邻居层号的最大/次大/第三大
        for(int u=1;u<=n;u++){
            int L1=0,L2=0,L3=0,i1=0,i2=0;
            for(int e=st[u];e<st[u+1];e++){
                int v=adj[e],L=lvl[v];
                if(L>=L1){L3=L2;L2=L1;L1=L;i2=i1;i1=v;}
                else if(L>=L2){L3=L2;L2=L;i2=v;}
                else if(L>L3){L3=L;}
            }
            two[u]=L2;three[u]=L3;id1[u]=i1;id2[u]=i2;
        }
        // 四、挂枝深度：先子树深度，再从上往下推向上的深度
        for(int i=1;i<=n;i++)dn[i]=0;
        int qt=0;
        que[qt++]=1;par[1]=0;
        for(int i=0;i<qt;i++){
            int u=que[i];
            for(int e=st[u];e<st[u+1];e++){
                int v=adj[e];
                if(v!=par[u]){par[v]=u;que[qt++]=v;}
            }
        }
        for(int i=n-1;i>=1;i--){
            int u=que[i];
            if(dn[u]+1>dn[par[u]])dn[par[u]]=dn[u]+1;
        }
        upv[1]=0;
        for(int i=0;i<n;i++){
            int u=que[i];
            int m1=0,m2=0,who=0;
            for(int e=st[u];e<st[u+1];e++){
                int v=adj[e];
                if(v==par[u])continue;
                int val=dn[v]+1;
                if(val>m1){m2=m1;m1=val;who=v;}
                else if(val>m2)m2=val;
            }
            for(int e=st[u];e<st[u+1];e++){
                int v=adj[e];
                if(v==par[u])continue;
                int other=(v==who)?m2:m1;
                int best=upv[u]>other?upv[u]:other;
                upv[v]=best+1;
            }
        }
        // 五、二分答案
        int lo=0,hi=maxLev;
        for(int r=0;r<=maxLev;r++)
            if(n-lvStart[r+1]<=K){hi=r;break;}
        for(int r=0;r<=hi;r++)
            if(n-lvStart[r+1]<=K+2*r){lo=r;break;}
        int ans;
        if(check(lo))ans=lo;
        else{
            int h2=hi;
            lo++;
            while(lo<h2){
                int mid=(lo+h2)>>1;
                if(check(mid))h2=mid;
                else lo=mid+1;
            }
            ans=lo;
        }
        cout<<ans<<'\n';
    }
    return 0;
}
